def find_path(graph, start, goal):

    def hill_climbing_search(current, goal, visited=None):
        if visited is None:
            visited = set()
        visited.add(current)
        if current == goal:
            return [current]
        if current not in graph:
            return None
        candidate_nodes = graph[current] - visited
        if not candidate_nodes:
            return None
        unvisited_nodes = set(candidate_nodes) - visited
        best_path = None
        for node in unvisited_nodes:
            path = hill_climbing_search(node, goal, visited | set([current]))
            if path:
                if not best_path or len(path) < len(best_path):
                    best_path = path
        return best_path if best_path else None
    return hill_climbing_search(start, goal)
