def find_path(graph, start, goal):
    # Initialize open sets and closed sets for both directions
    open_set_start = {start}
    open_set_goal = {goal}
    closed_set_start = set()
    closed_set_goal = set()

    # Initialize predecessor dictionary
    came_from_start = {}
    came_from_goal = {}

    # Initialize path costs
    g_score_start = {node: float('inf') for node in graph}
    g_score_goal = {node: float('inf') for node in graph}
    g_score_start[start] = 0
    g_score_goal[goal] = 0

    # Initialize f scores (estimated total cost from start to goal)
    f_score_start = {node: float('inf') for node in graph}
    f_score_goal = {node: float('inf') for node in graph}
    f_score_start[start] = heuristic(start, goal)
    f_score_goal[goal] = heuristic(goal, start)

    while open_set_start and open_set_goal:
        # Choose the node with the lowest f score from both open sets
        current_start = min(open_set_start, key=lambda x: f_score_start[x])
        current_goal = min(open_set_goal, key=lambda x: f_score_goal[x])

        # If we found the goal, we are done
        if current_start == current_goal:
            return reconstruct_path(came_from_start, came_from_goal, current_start)

        # Mark the current node as visited
        open_set_start.discard(current_start)
        open_set_goal.discard(current_goal)
        closed_set_start.add(current_start)
        closed_set_goal.add(current_goal)

        # Explore neighbors
        for neighbor in graph[current_start]:
            if neighbor in closed_set_goal:
                continue
            tentative_g_score = g_score_start[current_start] + heuristic(current_start, neighbor)
            if neighbor not in open_set_goal or tentative_g_score < g_score_goal[neighbor]:
                came_from_goal[neighbor] = current_start
                g_score_goal[neighbor] = tentative_g_score
                f_score_goal[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                if neighbor not in open_set_goal:
                    open_set_goal.add(neighbor)

        for neighbor in graph[current_goal]:
            if neighbor in closed_set_start:
                continue
            tentative_g_score = g_score_goal[current_goal] + heuristic(current_goal, neighbor)
            if neighbor not in open_set_start or tentative_g_score < g_score_start[neighbor]:
                came_from_start[neighbor] = current_goal
                g_score_start[neighbor] = tentative_g_score
