def heuristic(node, goal):
    x1, y1 = node
    x2, y2 = goal
    return abs(x1 - x2) + abs(y1 - y2)

def ida_star(graph, start, goal):

    def search(current_node, depth_limit, visited):
        if current_node == goal:
            return [current_node]
        visited.add(current_node)
        if current_node not in graph or not graph[current_node]:
            return None
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                path = search(neighbor, depth_limit, visited)
                if path:
                    return [current_node] + path
        return None

    def ida_star_helper(current_depth):
        visited = set()
        path = search(start, current_depth, visited)
        if path:
            return path
        return None
    current_depth = 0
    limit = heuristic(start, goal)
    while True:
        result = ida_star_helper(current_depth)
        if result:
            return result
        current_depth += 1
        limit = max(limit, heuristic(start, goal))
        if limit > current_depth:
            return None
