    if start == goal:
        return [start]
    forward_search = {start}
    backward_search = {goal}
    visited_forward = {start}
    visited_backward = {goal}
    forward_predecessors = {start: None}
    backward_predecessors = {goal: None}
    while forward_search and backward_search:
