            current_node = *min(forward_search, key=lambda x: len(graph[x]), default=None)
            if current_node is None:
                break
            forward_search.remove(current_node)
            for neighbor in graph.get(current_node, []):
                if neighbor in visited_forward:
                    continue
                visited_forward.add(neighbor)
                forward_search.add(neighbor)
                forward_predecessors[neighbor] = current_node
        else:
            current_node = *min(backward_search, key=lambda x: len(graph[x]), default=None)
            if current_node is None:
                break
            backward_search.remove(current_node)
            for neighbor in graph.get(current_node, []):
                if neighbor in visited_backward:
                    continue
                visited_backward.add(neighbor)
                backward_search.add(neighbor)
                backward_predecessors[neighbor] = current_node
        if current_node in backward_search:
            path = []
            current_node = current_node
            while current_node is not None:
                path.append(current_node)
                current_node = forward_predecessors.get(current_node, None)
            path.reverse()
            return path
    return None
