def reconstruct_path(start, goal, graph, distances):
    path = []
    current_node = goal
    while current_node != start:
        path.append(current_node)
        current_node = next((node for node in graph[current_node] if distances[node] == distances[current_node] - 1), None)
    path.append(start)
    path.reverse()
    return path
