def find_path(graph, start, goal):
    frontier_start = set([start])
    frontier_goal = set([goal])
    came_from_start = {start: None}
    came_from_goal = {goal: None}
    cost_from_start = {start: 0}
    cost_from_goal = {goal: 0}

    def get_next(node, cost):
        if cost_from_start[node] < cost_from_goal[node]:
            next_node = max(frontier_start & frontier_goal, key=lambda n: cost_from_start[n])
        else:
            next_node = min(frontier_start & frontier_goal, key=lambda n: cost_from_goal[n])
        return next_node
    while frontier_start and frontier_goal:
        next_start = get_next(next_node=start, cost=cost_from_start)
        next_goal = get_next(next_node=goal, cost=cost_from_goal)
        if next_start == next_goal:
            path = [next_start]
            while next_start in came_from_start:
                next_start = came_from_start[next_start]
                path.append(next_start)
            path.append(goal)
            path.reverse()
            return path
        else:
            frontier_start.discard(next_start)
            frontier_goal.discard(next_goal)
            for neighbor in graph[next_start]:
                if neighbor not in frontier_start:
                    frontier_start.add(neighbor)
                    came_from_start[neighbor] = next_start
                    cost_from_start[neighbor] = cost_from_start[next_start] + 1
            for neighbor in graph[next_goal]:
                if neighbor not in frontier_goal:
                    frontier_goal.add(neighbor)
                    came_from_goal[neighbor] = next_goal
                    cost_from_goal[neighbor] = cost_from_goal[next_goal] + 1
    return None

def find_path(graph, start, goal):
    stack = [(start, [start])]
    while stack:
        vertex, path = stack.pop()
        if vertex == goal:
            return path
        for neighbor in graph[vertex]:
            if neighbor not in path:
                new_path = path + [neighbor]
                stack.append((neighbor, new_path))
    return None
